par={}
par['Q']='M'; par['R']=par['Q']; par['K']='R'; par['Y']=par['K']
female={'M','R'}
def rel(a,b):
    if par.get(b)==a: return 'Mother' if a in female else 'Father'
    p=par.get(b)
    if p and par.get(p)==a: return ("Mother’s " if p in female else "Father’s ")+('mother' if a in female else 'father')
    return None
opts={'A':'Mother','B':'Father’s mother','C':'Mother’s mother','D':'Brother’s wife'}
r=rel('M','Y')
assert r==opts['C']
for k in 'ABD': assert r!=opts[k]

opts={'A':'MPS','B':'KNP','C':'TWZ','D':'DGJ'}
def ok(s): return all(ord(s[i+1])-ord(s[i])==3 for i in range(2))
odd=[k for k,v in opts.items() if not ok(v)]
assert odd==['B']
assert opts[odd[0]]=='KNP'
for k in 'ACD': assert opts[k]!=opts[odd[0]]

from fractions import Fraction as F
expr=['29','×','145','+','5','−','640','÷','15']
def ev(e):
    s=' '.join(e).replace('×','*').replace('÷','/').replace('−','-')
    toks=s.split(); s=' '.join('F(%s)'%t if t.isdigit() else t for t in toks)
    return eval(s)
opts={'A':('−','×'),'B':('÷','+'),'C':('−','+'),'D':('÷','×')}
good=[]
for k,(a,b) in opts.items():
    e=[b if t==a else a if t==b else t for t in expr]
    if ev(e)==216: good.append(k)
assert good==['B']

pat='LM_O_NPMRO_KU_TI'
opts={'A':'RPMO','B':'PNOR','C':'NORP','D':'NOPR'}
def fill(f):
    it=iter(f); return ''.join(next(it) if c=='_' else c for c in pat)
def ok(s):
    b=[s[i:i+4] for i in range(0,16,4)]
    for j,d in enumerate([3,1,2,-2]):
        if any(ord(b[i+1][j])-ord(b[i][j])!=d for i in range(3)): return False
    return True
good=[k for k,v in opts.items() if ok(fill(v))]
assert good==['C']

